const slugHeading = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
const plain = value => String(value).replace(/<[^>]*>/g, '')
const paragraphs = value => (Array.isArray(value) ? value : [value]).filter(Boolean)

export function diagnosticCatalog() {
  return DIAGNOSTIC_ARTICLES.map(({ id, theme, kind, meta }) => ({
    id, theme, kind,
    ...Object.fromEntries(['pt', 'en', 'es'].map(lang => [lang, { live, ...meta[lang] }])),
  }))
}

export function getDiagnosticArticle(id, lang) {
  const record = DIAGNOSTIC_ARTICLES.find(item => item.id === id)
  if (!record) throw new Error(`Unknown diagnostic article: ${id}`)
  const m = record.meta[lang]
  const c = record.content[lang]
  const blocks = []
  for (const section of c.sections) {
    blocks.push({ h2: section.h2, id: slugHeading(section.h2), toc: section.h2 })
    for (const p of paragraphs(section.p)) blocks.push({ p })
  }
  blocks.push({ summary: c.summary })
  blocks.push({ h2: lang === 'pt' ? 'ConclusÃ£o' : lang === 'en' ? 'Conclusion' : 'ConclusiÃ³n', id: 'conclusao', toc: lang === 'pt' ? 'ConclusÃ£o' : lang === 'en' ? 'Conclusion' : 'ConclusiÃ³n' })
  blocks.push({ p: c.conclusion })
  if (record.bridge?.[lang]) blocks.push({ bridge: record.bridge[lang] })

  const questions = c.sections.map(section => ({
    question: `${plain(section.h2).replace(/[?!.]+$/, '')}?`,
    answer: plain(paragraphs(section.p)[0]),
  }))
  questions.push({
    question: lang === 'pt' ? `O que fazer perante ${m.title.toLowerCase()}?` : lang === 'en' ? `What should you do about ${m.title.toLowerCase()}?` : `Â¿QuÃ© hacer ante ${m.title.toLowerCase()}?`,
    answer: plain(c.conclusion),
  })
  return {
    id: record.id,
    slug: m.slug,
    theme: record.theme,
    short: m.title,
    date: '2026-10-18',
    titleTag: titleTag(m.title, lang),
    description: m.teaser,
    keywords: [m.title.replace(/[?!:]/g, '').toLowerCase(), ...c.sections.map(section => plain(section.h2).replace(/[?¿]/g, '').toLowerCase()), record.theme === 'mitos' ? (lang === 'pt' ? 'mito ou verdade' : lang === 'en' ? 'myth or fact' : 'mito o verdad') : (lang === 'pt' ? 'avalia\u00e7\u00e3o do desenvolvimento infantil' : lang === 'en' ? 'child developmental assessment' : 'evaluaci\u00f3n del desarrollo infantil'), lang === 'pt' ? 'relat\u00f3rio cl\u00ednico infantil' : lang === 'en' ? 'child clinical report' : 'informe cl\u00ednico infantil'],
    h1: `<span class="word-highlight">${m.title}</span>`,
    lead: c.lead,
    blocks,
    faqTitle: lang === 'pt' ? 'Perguntas frequentes' : lang === 'en' ? 'Frequently asked questions' : 'Preguntas frecuentes',
    faq: questions.map(({ question, answer }) => [question, answer]),
    sources: record.sources,
    related: record.related,
  }
}
